initApi.adaptor:
function addHasChildrenToItems(arr) {
  arr.forEach(item => {
    if (item.children && item.children.length > 0) {
      item.hasChildren = true;
      addHasChildrenToItems(item.children);
    } else {
      item.hasChildren = false;
    }
  });
  return arr
}
return {
  ...payload,
  data: addHasChildrenToItems(payload.data.items)
}
